import{_ as e,o as a,c as d,a0 as r}from"./chunks/framework.DzvPB4Y-.js";const u=JSON.parse('{"title":"二维装箱（BPP2D）：适用问题与学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp2d/index.md","filePath":"zh-cn/frameworks/bpp2d/index.md"}'),o={name:"zh-cn/frameworks/bpp2d/index.md"};function i(l,t,n,h,c,s){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="二维装箱-bpp2d-适用问题与学习路线" tabindex="-1">二维装箱（BPP2D）：适用问题与学习路线 <a class="header-anchor" href="#二维装箱-bpp2d-适用问题与学习路线" aria-label="Permalink to &quot;二维装箱（BPP2D）：适用问题与学习路线&quot;">​</a></h1><p>把已有矩形零件排到板面上，检查旋转、间距、越界和重叠，再比较板材消耗与余料。二维装箱不仅是画坐标，还需要需求覆盖、板型选择和最终校验。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>角色</th><th>核心字段</th></tr></thead><tbody><tr><td>物品</td><td><code>ActualItem</code></td><td>输入</td><td>形状、重量和旋转许可</td></tr><tr><td>板型</td><td><code>SheetType</code></td><td>输入</td><td>宽高、承重、类型 ID</td></tr><tr><td>候选排布</td><td><code>Layer</code></td><td>中间概念</td><td>携带板型的放置集合</td></tr><tr><td>生成请求</td><td><code>Bpp2dLayerGenerationRequest</code></td><td>输入</td><td>物品、板型、间距与候选限制</td></tr><tr><td>应用服务</td><td><code>ColumnGenerationApplicationService</code></td><td>调用 / 校验入口</td><td>生成、分配、装箱与 KPI / 渲染</td></tr><tr><td>装箱结果与指标</td><td><code>PackingResult</code> / <code>response.packing</code></td><td>输出</td><td>板材、放置、空闲矩形区域、面积与终止诊断</td></tr></tbody></table><p>矩形支持可选 90° 旋转；圆形与混合形状属于后续专题。内部相交才算重叠，相切不算重叠。实际面积与外接面积应分别阅读。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Kotlin 与 Rust 的入口差异</p><p>两种语言都有 <code>ColumnGenerationApplicationService</code>。Kotlin 接收求解器；Rust 需要分别提供受限主问题和最终整数求解的执行器。Rust 未配置这两个执行器时，不会完成对应的整数优化。</p></div><p>先理解候选排布和最终几何校验，再配置受限主问题、候选搜索和最终整数求解。受限主问题只考虑当前已生成的候选；列生成等算法名称见<a href="./../#terminology">术语说明</a>。几何约束由框架提供，应用应复用这些规则。</p><p>这里的应用入口本身就是列生成流程，没有名为 <code>Bpp2dMilp</code> 的对等切换入口。小实例先固定板型并限制候选；多板型时逐步扩大每轮候选与迭代预算。参数代码见<a href="./business-scenario.html#entry-budget">第二课</a>。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>几何上放得下，不等于满足断头台切割工艺。生产需求、切分树与卷材消耗见 <a href="./../csp2d/">CSP2D</a>。</li><li>圆形面积为实际圆面积，不能用外接矩形面积冒充装载率。</li><li>面积消耗、板数和板型费用是不同目标；加权求和不自动保证“先优化第一目标，再优化第二目标”的严格优先级。</li><li>仅有候选生成或模拟执行，不构成原生求解或完整问题最优性证据。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-layout.html">第一次二维排样</a>，从矩形和单板型开始。</li><li>修改旋转与间距，再引入多板型与费用。新生成策略应接生成器接口，而不是复制求解循环。</li><li>添加业务规则前，明确它约束单个候选还是多个候选的组合选择。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp2d/README_ch.md" target="_blank" rel="noreferrer">Kotlin API 与形状支持矩阵</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp2d/README_ch.md" target="_blank" rel="noreferrer">Rust API 与执行器接口说明</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./first-layout.html">第一次二维排样</a>。完成后再学<a href="./business-scenario.html">多板型、旋转与间距</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',18)])])}const f=e(o,[["render",i]]);export{u as __pageData,f as default};
